// This code processes audio files and extracts amplitude envelopes

function amplitudeEnvelope(signal, frameLength, hopLength, feature) {
const output = [];

for (let i = 0; i < signal.length; i += hopLength) {
const frame = signal.slice(i, i + frameLength);
if (!frame.length) continue;

let value = 0;

switch(feature) {
case 'MAX':
value = Math.max(...frame);
break;
case 'MIN':
value = Math.min(...frame);
break;
case 'MEAN':
value = frame.reduce((a, b) => a + b, 0) / frame.length;
break;
case 'MEDIAN':
const sorted = [...frame].sort((a, b) => a - b);
const mid = Math.floor(sorted.length / 2);
value = sorted.length % 2 === 0
? (sorted[mid - 1] + sorted[mid]) / 2
: sorted[mid];
break;
}

output.push(value);
}

return output;
}

